#!/usr/bin/env bash
# Installs and configures WordPress for local development.
# Run inside the web container by DDEV's post-start hook; safe to re-run.
# wp-config.php and wp-config-ddev.php are generated by DDEV.
set -euo pipefail

cd /var/www/html/wordpress

if [ ! -f wp-load.php ]; then
	wp core download
fi

if ! wp core is-installed 2>/dev/null; then
	wp core install \
		--url="$DDEV_PRIMARY_URL" \
		--title="Kudos Donations" \
		--admin_user=admin \
		--admin_password=password \
		--admin_email=admin@example.com \
		--skip-email
fi

# Take ownership of the wp-config.php DDEV generated. Without this DDEV regenerates it on
# every start, with new salts (logging everyone out). Database settings and URLs still come
# from wp-config-ddev.php, which DDEV keeps managing.
sed -i '/#ddev-generated/d' wp-config.php

# Development constants, written into the custom values section of wp-config.php.
wp config set WP_DEBUG_LOG true --raw
wp config set WP_DEBUG_DISPLAY true --raw
wp config set SCRIPT_DEBUG true --raw
wp config set KUDOS_DEMO_MODE false --raw
wp config set QM_ENABLE_CAPS_PANEL false --raw

if ! wp plugin is-installed query-monitor; then
	wp plugin install query-monitor
fi

wp plugin activate kudos-donations query-monitor
